create table public.hostels(id uuid primary key default gen_random_uuid(),campus_id uuid not null references public.campuses(id) on delete restrict,name text not null,eligibility text not null default 'all',is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(campus_id,name));
create table public.hostel_blocks(id uuid primary key default gen_random_uuid(),hostel_id uuid not null references public.hostels(id) on delete restrict,code text not null,name text not null,is_active boolean not null default true,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(hostel_id,code));
create table public.hostel_rooms(id uuid primary key default gen_random_uuid(),block_id uuid not null references public.hostel_blocks(id) on delete restrict,room_number text not null,capacity smallint not null,room_type text not null,status text not null default 'active',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(block_id,room_number),constraint room_capacity check(capacity>0));
create table public.hostel_room_allocations(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.hostel_rooms(id) on delete restrict,resident_id uuid not null references public.profiles(id) on delete restrict,starts_on date not null,ends_on date,status text not null default 'active',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),constraint allocation_dates check(ends_on is null or ends_on>=starts_on));
create table public.outpass_requests(id uuid primary key default gen_random_uuid(),resident_id uuid not null references public.profiles(id) on delete restrict,destination text not null,reason text not null,depart_at timestamptz not null,return_at timestamptz not null,status text not null default 'pending',reviewer_id uuid references public.profiles(id) on delete set null,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),constraint outpass_dates check(return_at>depart_at));
create table public.hostel_complaints(id uuid primary key default gen_random_uuid(),resident_id uuid not null references public.profiles(id) on delete restrict,room_id uuid references public.hostel_rooms(id) on delete set null,category text not null,description text not null,status text not null default 'open',assignee_id uuid references public.profiles(id) on delete set null,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table public.hostel_attendance(id uuid primary key default gen_random_uuid(),hostel_id uuid not null references public.hostels(id) on delete restrict,resident_id uuid not null references public.profiles(id) on delete restrict,attendance_date date not null,status text not null,marked_by uuid not null references public.profiles(id) on delete restrict,notes text not null default '',created_at timestamptz not null default timezone('utc',now()),unique(resident_id,attendance_date));
create index allocations_resident_idx on public.hostel_room_allocations(resident_id,status); create index outpasses_resident_idx on public.outpass_requests(resident_id,status); create index complaints_queue_idx on public.hostel_complaints(status,created_at); create index attendance_hostel_idx on public.hostel_attendance(hostel_id,attendance_date);
alter table public.hostels enable row level security;alter table public.hostel_blocks enable row level security;alter table public.hostel_rooms enable row level security;alter table public.hostel_room_allocations enable row level security;alter table public.outpass_requests enable row level security;alter table public.hostel_complaints enable row level security;alter table public.hostel_attendance enable row level security;
create policy hostel_catalog_read on public.hostels for select to authenticated using(true);create policy hostel_catalog_manage on public.hostels for all to authenticated using(public.has_permission('hostel.manage',campus_id)) with check(public.has_permission('hostel.manage',campus_id));create policy block_read on public.hostel_blocks for select to authenticated using(true);create policy block_manage on public.hostel_blocks for all to authenticated using(public.has_permission('hostel.manage')) with check(public.has_permission('hostel.manage'));create policy room_read on public.hostel_rooms for select to authenticated using(true);create policy room_manage on public.hostel_rooms for all to authenticated using(public.has_permission('hostel.manage')) with check(public.has_permission('hostel.manage'));create policy allocations_read on public.hostel_room_allocations for select to authenticated using(resident_id=auth.uid() or public.has_permission('hostel.allocate'));create policy allocations_write on public.hostel_room_allocations for all to authenticated using(public.has_permission('hostel.allocate')) with check(public.has_permission('hostel.allocate'));create policy outpasses_read on public.outpass_requests for select to authenticated using(resident_id=auth.uid() or public.has_permission('hostel.outpasses.manage'));create policy outpasses_insert on public.outpass_requests for insert to authenticated with check(resident_id=auth.uid());create policy outpasses_update on public.outpass_requests for update to authenticated using(resident_id=auth.uid() or public.has_permission('hostel.outpasses.manage')) with check(resident_id=auth.uid() or public.has_permission('hostel.outpasses.manage'));create policy complaints_read on public.hostel_complaints for select to authenticated using(resident_id=auth.uid() or public.has_permission('hostel.complaints.manage'));create policy complaints_write on public.hostel_complaints for all to authenticated using(resident_id=auth.uid() or public.has_permission('hostel.complaints.manage')) with check(resident_id=auth.uid() or public.has_permission('hostel.complaints.manage'));create policy attendance_read on public.hostel_attendance for select to authenticated using(resident_id=auth.uid() or public.has_permission('hostel.attendance.manage'));create policy attendance_write on public.hostel_attendance for all to authenticated using(public.has_permission('hostel.attendance.manage')) with check(public.has_permission('hostel.attendance.manage'));
